/**
 * Service for processing tick-related calculations
 * Pure functions for tick alignment and validation
 */
export class TickProcessor {
  
  /**
   * Align ticks to the nearest valid tick for the given spacing
   */
  alignTicksToSpacing(tickLower: number, tickUpper: number, tickSpacing: number): {
    alignedTickLower: number
    alignedTickUpper: number
  } {
    const alignedTickLower = Math.floor(tickLower / tickSpacing) * tickSpacing
    let alignedTickUpper = Math.ceil(tickUpper / tickSpacing) * tickSpacing

    // Ensure minimum range - if alignment made them equal, add spacing
    if (alignedTickLower >= alignedTickUpper) {
      alignedTickUpper = alignedTickLower + tickSpacing
    }


    return {
      alignedTickLower,
      alignedTickUpper
    }
  }

  /**
   * Validate tick range
   */
  validateTickRange(tickLower: number, tickUpper: number, tickSpacing: number): {
    valid: boolean
    error?: string
  } {
    // Check tick order
    if (tickLower >= tickUpper) {
      return { valid: false, error: 'tickLower must be less than tickUpper' }
    }

    // Check tick spacing alignment
    if (tickLower % tickSpacing !== 0) {
      return { valid: false, error: `tickLower must be divisible by ${tickSpacing}` }
    }

    if (tickUpper % tickSpacing !== 0) {
      return { valid: false, error: `tickUpper must be divisible by ${tickSpacing}` }
    }

    // Check tick bounds (Uniswap V3 limits)
    const MIN_TICK = -887272
    const MAX_TICK = 887272

    if (tickLower < MIN_TICK || tickLower > MAX_TICK) {
      return { valid: false, error: `tickLower out of bounds: ${MIN_TICK} to ${MAX_TICK}` }
    }

    if (tickUpper < MIN_TICK || tickUpper > MAX_TICK) {
      return { valid: false, error: `tickUpper out of bounds: ${MIN_TICK} to ${MAX_TICK}` }
    }

    return { valid: true }
  }

  /**
   * Get valid tick spacings for Abstract DEX
   */
  getValidTickSpacings(): number[] {
    return [1, 100, 200, 2000]
  }

  /**
   * Check if tick spacing is valid for Abstract DEX
   */
  isValidTickSpacing(tickSpacing: number): boolean {
    return this.getValidTickSpacings().includes(tickSpacing)
  }
}