import { ethers } from 'ethers'
import { ProcessedTokens, ABSTRACT_TICK_SPACINGS } from '../types/AbstractLpTypes'
import { UniverseChainId } from 'uniswap/src/features/chains/types'

/**
 * Service for processing tokens and amounts
 * All pure functions for easy testing
 */
export class TokenProcessor {
  private static readonly WETH_ADDRESSES = {
    [UniverseChainId.Sepolia]: '0x9edcde0257f2386ce177c3a7fcdd97787f0d841d', // Abstract testnet
    [UniverseChainId.Mainnet]: '0x3439153EB7AF838Ad19d56E1571FBD09333C2809',  // Abstract mainnet
  }

  /**
   * Process tokens and amounts for V3 position creation
   * Handles token sorting, ETH conversion, and amount reordering
   */
  processTokensAndAmounts(
    token0: string,
    token1: string,
    amount0: string,
    amount1: string,
    chainId: UniverseChainId,
    slippageTolerance: number
  ): ProcessedTokens {
    // 1. Track original ETH tokens
    const isToken0OriginallyETH = this.isNativeETH(token0)
    const isToken1OriginallyETH = this.isNativeETH(token1)

    // 2. Convert ETH to WETH addresses
    let finalToken0 = isToken0OriginallyETH ? this.getWethAddress(chainId) : token0
    let finalToken1 = isToken1OriginallyETH ? this.getWethAddress(chainId) : token1

    let finalAmount0 = amount0
    let finalAmount1 = amount1

    // 3. Sort tokens (Uniswap V3 requirement: token0 < token1)
    if (finalToken0.toLowerCase() > finalToken1.toLowerCase()) {
      [finalToken0, finalToken1] = [finalToken1, finalToken0];
      [finalAmount0, finalAmount1] = [finalAmount1, finalAmount0]
    }

    // 4. Calculate minimum amounts with slippage
    const slippageMultiplier = (100 - slippageTolerance) / 100
    const finalAmount0Min = ethers.BigNumber.from(finalAmount0)
      .mul(Math.floor(slippageMultiplier * 100))
      .div(100)
      .toString()
    const finalAmount1Min = ethers.BigNumber.from(finalAmount1)
      .mul(Math.floor(slippageMultiplier * 100))
      .div(100)
      .toString()

    return {
      finalToken0,
      finalToken1,
      finalAmount0,
      finalAmount1,
      finalAmount0Min,
      finalAmount1Min,
      isToken0OriginallyETH,
      isToken1OriginallyETH
    }
  }

  /**
   * Check if a token address represents native ETH
   */
  isNativeETH(tokenAddress: string): boolean {
    if (!tokenAddress) return false
    
    const addr = tokenAddress.toLowerCase()
    return (
      addr === 'native' ||
      addr === 'eth' ||
      addr === '0x0000000000000000000000000000000000000000'
    )
  }

  /**
   * Get WETH address for a given chain
   */
  getWethAddress(chainId: UniverseChainId): string {
    return TokenProcessor.WETH_ADDRESSES[chainId] || TokenProcessor.WETH_ADDRESSES[UniverseChainId.Mainnet]
  }

  /**
   * Convert fee amount to tick spacing for Abstract DEX
   */
  feeToTickSpacing(fee: number): number {
    return ABSTRACT_TICK_SPACINGS[fee] || 200 // Default to 200 if unknown
  }

  /**
   * Validate token addresses
   */
  validateTokens(token0: string, token1: string): { valid: boolean; error?: string } {
    if (!token0 || !token1) {
      return { valid: false, error: 'Missing token addresses' }
    }

    if (token0.toLowerCase() === token1.toLowerCase()) {
      return { valid: false, error: 'Token addresses cannot be identical' }
    }

    return { valid: true }
  }

  /**
   * Calculate ETH value to send with transaction
   */
  calculateEthValue(processedTokens: ProcessedTokens): string {
    if (processedTokens.isToken0OriginallyETH) {
      return processedTokens.finalAmount0
    }
    if (processedTokens.isToken1OriginallyETH) {
      return processedTokens.finalAmount1
    }
    return '0'
  }
}